fn main() {
    let items = vec![
        ("pen", 3, 4),
        ("pad", 9, 2),
        ("ink", 5, 3),
    ];
    let mut total_cost = 0;
    let mut max_cost = 0;
    let mut max_item = "";
    for (name, price, quantity) in items {
        let cost = price * quantity;
        total_cost += cost;
        if cost > max_cost {
            max_cost = cost;
            max_item = name;
        }
    }
    println!("{}", total_cost);
    println!("{}", max_item);
}
